{
  "name": "USB-CTR04/08 多通道标度计数器",
  "name_en": "USB-CTR04/08 Multi-Channel Scaler",
  "manufacturer": "Measurement Computing",
  "description": "Measurement Computing 的 USB-CTR04/USB-CTR08 多通道标度计数器，用于对脉冲或计数通道进行定时采集。该设备支持内部/外部模式、连续采集、标量采集、阵列采集和 ROI 模式，可启动、停止、清除并读取 MCS/MCA 数据，常用于步进扫描或连续扫描实验中的计数信号采集。",
  "description_en": "Measurement Computing USB-CTR04/USB-CTR08 multi-channel scaler for time-resolved pulse or count acquisition. It supports internal and external modes, continuous, scaler, array, and ROI acquisition modes, and can start, stop, erase, and read MCS/MCA data for step-scan or slew-scan experiments.",
  "tag_hints": [
    "multi-channel scaler",
    "counter/timer acquisition",
    "MCS",
    "MCA readout",
    "external triggering",
    "step scanning",
    "slew scanning"
  ],
  "actions": [
    {
      "action_name": "auto-ContinuousMode",
      "description": "设置为连续采集模式。",
      "description_en": "Set the device to continuous acquisition mode."
    },
    {
      "action_name": "auto-ExternalMode",
      "description": "设置为外部模式，使用外部触发或外部计数相关选项进行采集。",
      "description_en": "Set the device to external mode for acquisition using external trigger/count-related options."
    },
    {
      "action_name": "auto-InternalMode",
      "description": "设置为内部定时模式。",
      "description_en": "Set the device to internal timing mode."
    },
    {
      "action_name": "auto-NDArrayMode",
      "description": "设置为阵列采集模式，用于连续扫描采集。",
      "description_en": "Set the device to array acquisition mode for slew-scan data collection."
    },
    {
      "action_name": "auto-ROIMode",
      "description": "设置为 ROI 模式，用于连续扫描采集。",
      "description_en": "Set the device to ROI mode for slew-scan acquisition."
    },
    {
      "action_name": "auto-ScalerMode",
      "description": "设置为标量模式，用于步进扫描采集。",
      "description_en": "Set the device to scaler mode for step-scan acquisition."
    },
    {
      "action_name": "auto-erase",
      "description": "清除当前 MCS 采集数据。",
      "description_en": "Erase the current MCS acquisition data."
    },
    {
      "action_name": "auto-mcaNread",
      "description": "读取指定数量的 MCA 数据。",
      "description_en": "Read the requested number of MCA datasets."
    },
    {
      "action_name": "auto-read_all_mcas",
      "description": "读取全部 MCA 数据。",
      "description_en": "Read all available MCA data."
    },
    {
      "action_name": "auto-read_scaler_config",
      "description": "读取标量通道名称和计算配置。",
      "description_en": "Read scaler channel names and calculation configuration."
    },
    {
      "action_name": "auto-readmca",
      "description": "读取单个 MCS/MCA 数据谱。",
      "description_en": "Read a single MCS/MCA spectrum."
    },
    {
      "action_name": "auto-save_arraydata",
      "description": "将 MCA 阵列数据保存为 ASCII 文件。",
      "description_en": "Save MCA array data to an ASCII file."
    },
    {
      "action_name": "auto-set_dwelltime",
      "description": "设置驻留时间。",
      "description_en": "Set the dwell time."
    },
    {
      "action_name": "auto-start",
      "description": "启动 MCS 采集。",
      "description_en": "Start MCS acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止 MCS 采集。",
      "description_en": "Stop MCS acquisition."
    },
    {
      "action_name": "auto-get_arraydata",
      "description": "获取阵列数据。",
      "description_en": "Get array data."
    },
    {
      "action_name": "auto-pre_scan",
      "description": "在扫描前准备计数器采集。",
      "description_en": "Prepare the counter acquisition before a scan."
    },
    {
      "action_name": "auto-apply_offsets",
      "description": "应用已配置的偏移量。",
      "description_en": "Apply configured offsets."
    },
    {
      "action_name": "auto-arm",
      "description": "布防设备以等待采集触发。",
      "description_en": "Arm the device to await acquisition triggering."
    },
    {
      "action_name": "auto-disarm",
      "description": "撤防设备并退出待采集状态。",
      "description_en": "Disarm the device and leave the armed acquisition state."
    },
    {
      "action_name": "auto-post_scan",
      "description": "在扫描结束后完成计数器收尾处理。",
      "description_en": "Finalize the counter after a scan."
    },
    {
      "action_name": "auto-config_filesaver",
      "description": "配置采集数据的文件保存设置。",
      "description_en": "Configure file-saving settings for acquired data."
    }
  ]
}

